package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.data.UserPreferences;

final class PreferencesDialog {
    private final Dialog<UserPreferences> dialog=new Dialog<>();private final ComboBox<UserPreferences.Theme> theme=new ComboBox<>();private final ComboBox<UserPreferences.Language> language=new ComboBox<>();private final ComboBox<String> locale=new ComboBox<>();private final Spinner<Integer> digits=new Spinner<>(0,12,6),font=new Spinner<>(11,24,13),states=new Spinner<>(10,250,100,10),budget=new Spinner<>(1,64,8),cells=new Spinner<>(1000,5000000,5000000,100000);private final Label status=new Label();private final ComboBox<UserPreferences.Motion> motion=new ComboBox<>();private final ComboBox<UserPreferences.Accent> accent=new ComboBox<>();private final ComboBox<UserPreferences.Density> density=new ComboBox<>();private final ComboBox<UserPreferences.Layout> layout=new ComboBox<>();private final ComboBox<UserPreferences.ChartPreset> chartPreset=new ComboBox<>();private final CheckBox grid=new CheckBox("Show model grid"),snap=new CheckBox("Snap construct dragging to the 24-unit grid");
    private PreferencesDialog(Window owner,UserPreferences current){dialog.initOwner(owner);dialog.setTitle("Preferences");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);theme.getItems().setAll(UserPreferences.Theme.values());theme.setConverter(new javafx.util.StringConverter<>(){public String toString(UserPreferences.Theme value){return value==null?"":switch(value){case LIGHT->"Light";case DARK->"Dark";case SYSTEM->"System (follow device)";case HIGH_CONTRAST->"High contrast";};}public UserPreferences.Theme fromString(String value){return UserPreferences.Theme.valueOf(value);}});language.getItems().setAll(UserPreferences.Language.values());language.setConverter(new javafx.util.StringConverter<>(){public String toString(UserPreferences.Language value){return value==null?"":switch(value){case ENGLISH->"English";case SPANISH->"Español";case FRENCH->"Français";case GERMAN->"Deutsch";};}public UserPreferences.Language fromString(String value){return UserPreferences.Language.valueOf(value);}});locale.getItems().setAll("en-US","en-GB","es-ES","fr-FR","de-DE","pt-BR","zh-CN","ja-JP","ar-SA","hi-IN");locale.setConverter(new javafx.util.StringConverter<>(){public String toString(String tag){return tag==null?"":Locale.forLanguageTag(tag).getDisplayName(Locale.ENGLISH)+" ["+tag+"]";}public String fromString(String value){return value;}});motion.getItems().setAll(UserPreferences.Motion.values());accent.getItems().setAll(UserPreferences.Accent.values());density.getItems().setAll(UserPreferences.Density.values());layout.getItems().setAll(UserPreferences.Layout.values());chartPreset.getItems().setAll(UserPreferences.ChartPreset.values());GridPane form=new GridPane();form.setHgap(12);form.setVgap(9);form.setPadding(new Insets(12));Control[] controls={theme,language,locale,digits,font,states,budget,cells,motion,accent,density,layout,chartPreset,grid,snap};String[] names={"Theme","Navigation language","Table number locale","Decimal places","Font size","Undo states","Undo budget (MiB)","Dataset cell limit","Animations","Accent color","Layout density","Workspace layout","Chart style","Model grid","Drag alignment"};for(int i=0;i<controls.length;i++){form.add(UiAppearance.label(names[i]),0,i);form.add(controls[i],1,i);controls[i].setMaxWidth(Double.MAX_VALUE);controls[i].setAccessibleText(names[i]);if(controls[i] instanceof Spinner<?> spinner)spinner.setEditable(true);}Button defaults=UiAppearance.button("Reset defaults");defaults.setOnAction(event->set(UserPreferences.defaults()));Label note=UiAppearance.label("Light and Dark are explicit choices; System follows live device appearance changes where supported. Full animations respect the device reduced-motion setting. Navigation has English, Spanish, French and German labels, with English fallback. Scientific notes and your data/model names stay unchanged. Number formatting applies to newly rendered tables; archived report text keeps its original format. Numeric calculations and numeric archives stay unchanged. Memory limits apply to future imports/opens; changing undo limits starts a fresh undo history. The JVM heap is controlled by the launcher.");note.setWrapText(true);note.setMaxWidth(520);VBox content=new VBox(10,form,defaults,note,status);content.setPadding(new Insets(12));ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(720);dialog.getDialogPane().setContent(scroll);var save=dialog.getDialogPane().lookupButton(ButtonType.OK);save.addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{read();}catch(RuntimeException problem){status.setText(problem.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?read():null);set(current);}
    private void set(UserPreferences value){theme.setValue(value.theme());motion.setValue(value.motion());accent.setValue(value.accent());density.setValue(value.density());layout.setValue(value.layout());chartPreset.setValue(value.chartPreset());grid.setSelected(value.showGrid());snap.setSelected(value.snapToGrid());language.setValue(value.language());locale.setValue(value.numberLocale());digits.getValueFactory().setValue(value.fractionDigits());font.getValueFactory().setValue(value.fontSize());states.getValueFactory().setValue(value.historyStates());budget.getValueFactory().setValue(value.historyMiB());cells.getValueFactory().setValue((int)value.maximumDataCells());}
    private int integer(Spinner<Integer> spinner){return Integer.parseInt(spinner.getEditor().getText().strip());}
    private UserPreferences read(){return new UserPreferences(theme.getValue(),language.getValue(),locale.getValue(),integer(digits),integer(font),integer(states),integer(budget),integer(cells),motion.getValue(),accent.getValue(),density.getValue(),layout.getValue(),chartPreset.getValue(),grid.isSelected(),snap.isSelected());}
    static Optional<UserPreferences> show(Window owner,UserPreferences current){return new PreferencesDialog(owner,current).dialog.showAndWait();}
    static UserPreferences smoke(Window owner,java.nio.file.Path screenshot)throws Exception{var editor=new PreferencesDialog(owner,UserPreferences.defaults());editor.dialog.show();editor.set(new UserPreferences(UserPreferences.Theme.DARK,UserPreferences.Language.FRENCH,"fr-FR",4,16,40,4,1000000));if(editor.read().fontSize()!=16||!editor.read().numberLocale().equals("fr-FR"))throw new AssertionError("Preference controls did not bind");editor.font.getEditor().setText("99");((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing()||editor.status.getText().isBlank())throw new AssertionError("Invalid preferences were accepted");editor.font.getEditor().setText("16");var value=editor.read();editor.dialog.getDialogPane().applyCss();editor.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(screenshot);GraphicExport.png(screenshot,editor.dialog.getDialogPane(),1);editor.dialog.setResult(null);editor.dialog.close();return value;}
}
